mapper.select:
SELECT d.id, d.knowledge_id AS knowledgeId, d.doc_title AS docTitle, d.doc_source_type AS docSourceType, d.file_suffix AS fileSuffix, d.file_size AS fileSize, d.slice_mode AS sliceMode, d.recall_count AS recallCount, d.status, d.create_time AS createTime FROM bedrock_ai_knowledge_doc d WHERE d.is_deleted = 0
AND d.knowledge_id = #{param.knowledgeId}
AND d.doc_title LIKE concat('%', #{param.docTitle}, '%')
AND d.doc_source_type = #{param.docSourceType}
AND d.status = #{param.status}
ORDER BY d.create_time DESC
